#include <bits/stdc++.h>
using namespace std;
const int MAXN = 200005;
int par[MAXN], sz[MAXN];
long long w[MAXN];  // w[x] = pos[x] - pos[par[x]]
int find(int x) {
    if (par[x] == x) return x;
    int p = par[x], r = find(p);
    w[x] += w[p];  // w[p] is now pos[p] - pos[r]
    par[x] = r;
    return r;
}
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        int n, m; cin >> n >> m;
        for (int i = 1; i <= n; i++) par[i] = i, sz[i] = 1, w[i] = 0;
        bool ok = true;
        while (m--) {
            int a, b; long long d; cin >> a >> b >> d;
            if (!ok) continue;
            int ra = find(a), rb = find(b);
            if (ra == rb) { if (w[a] - w[b] != d) ok = false; continue; }
            long long diff = d - w[a] + w[b];  // pos[ra] - pos[rb]
            if (sz[ra] < sz[rb]) { par[ra] = rb; w[ra] = diff; sz[rb] += sz[ra]; }
            else { par[rb] = ra; w[rb] = -diff; sz[ra] += sz[rb]; }
        }
        cout << (ok ? "YES" : "NO") << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<long long> a(n);
        for (auto &x : a) scanf("%lld", &x);
        long long A = a[0], E = 0, ans = 0;  // previous final value = A * 2^E
        for (int i = 1; i < n; i++) {
            long long k = max(0LL, E - 34);
            while (true) {  // smallest k with a[i]*2^k >= A*2^E
                long long tt = min(k, E);
                __int128 L = (__int128)a[i] << (k - tt);
                __int128 R = (__int128)A << (E - tt);
                if (L >= R) break;
                k++;
            }
            ans += k;
            A = a[i]; E = k;
        }
        printf("%lld\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        vector<int> deg(n + 1, 0);
        for (int i = 0; i < n - 1; i++) {
            int u, v; cin >> u >> v; deg[u]++; deg[v]++;
        }
        string s; cin >> s;
        long long A0 = 0, A1 = 0, Q = 0, P = 0;  // known-0 leaves, known-1 leaves, ? leaves, ? internal
        for (int v = 2; v <= n; v++) {
            char c = s[v - 1];
            if (deg[v] == 1) {  // leaf
                if (c == '0') A0++; else if (c == '1') A1++; else Q++;
            } else if (c == '?') P++;
        }
        long long ans;
        char r = s[0];
        if (r == '?') {
            long long S = (A0 + A1 + Q + (P & 1)) / 2;
            ans = max(max(A0, A1) + Q / 2, S);
        } else if (r == '1') {
            ans = A0 + (Q + 1) / 2;
        } else {
            ans = A1 + (Q + 1) / 2;
        }
        cout << ans << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int n, x; vector<int> p;
int bs() { int l = 1, r = n + 1; while (r - l > 1) { int m = (l + r) / 2; if (p[m] <= x) l = m; else r = m; } return l; }
bool ok() { return p[bs()] == x; }
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        scanf("%d %d", &n, &x); p.assign(n + 1, 0);
        int q = 0;
        for (int i = 1; i <= n; i++) { scanf("%d", &p[i]); if (p[i] == x) q = i; }
        if (ok()) { puts("0"); continue; }
        vector<int> S = {1, n, bs(), q};
        int l = 1, r = n + 1;
        while (r - l > 1) { int m = (l + r) / 2; S.push_back(m); if (p[m] <= x) l = m; else r = m; }
        int cb = 0, cs = 0;
        for (int i = 1; i <= n; i++) {
            if (p[i] > x && cb < 2) { S.push_back(i); cb++; }
            if (p[i] < x && cs < 2) { S.push_back(i); cs++; }
        }
        sort(S.begin(), S.end()); S.erase(unique(S.begin(), S.end()), S.end());
        vector<pair<int, int>> pr;
        for (size_t a = 0; a < S.size(); a++) for (size_t b = a + 1; b < S.size(); b++) pr.push_back({S[a], S[b]});
        vector<pair<int, int>> ans; bool found = false;
        for (auto [a, b] : pr) { swap(p[a], p[b]); if (ok()) { ans = {{a, b}}; found = true; } swap(p[a], p[b]); if (found) break; }
        for (size_t i = 0; i < pr.size() && !found; i++) {
            auto [a, b] = pr[i]; swap(p[a], p[b]);
            for (size_t j = 0; j < pr.size() && !found; j++) {
                auto [c, d] = pr[j]; swap(p[c], p[d]);
                if (ok()) { ans = {{a, b}, {c, d}}; found = true; }
                swap(p[c], p[d]);
            }
            swap(p[a], p[b]);
        }
        printf("%d\n", (int)ans.size());
        for (auto [a, b] : ans) printf("%d %d\n", a, b);
    }
}

