int main() {
    int t; scanf("%d", &t);
    while (t--) {
        long long n, m; scanf("%lld %lld", &n, &m);
        long long z = n - m, g = m + 1;             // zeros, and groups of zeros
        long long q = z / g, rem = z % g;           // spread zeros as evenly as possible
        auto tri = [](long long x) { return x * (x + 1) / 2; };
        long long zeroSub = rem * tri(q + 1) + (g - rem) * tri(q);  // substrings with no 1
        printf("%lld\n", n * (n + 1) / 2 - zeroSub);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<long long> a(n), b(n);
        for (int i = 0; i < n; i++) scanf("%lld %lld", &a[i], &b[i]);
        const long long LIM = 10000000000000LL;  // 1e13: L/b_i must divide a_i <= 1e9
        int blocks = 0, l = 0;
        while (l < n) {
            blocks++;
            long long L = b[l];
            int r = l + 1;
            while (r < n) {
                long long nL = L / __gcd(L, b[r]) * b[r];
                if (nL > LIM) break;
                if (nL == L) {
                    if (a[r] % (L / b[r])) break;
                } else {
                    bool ok = true;
                    for (int i = l; i <= r && ok; i++) if (a[i] % (nL / b[i])) ok = false;
                    if (!ok) break;
                    L = nL;
                }
                r++;
            }
            l = r;
        }
        printf("%d\n", blocks);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; scanf("%d", &n);
    vector<int> a(n);
    for (auto &x : a) scanf("%d", &x);
    int l = 0, r = n - 1, last = 0;
    string res;
    while (l <= r) {
        bool cl = a[l] > last, cr = a[r] > last;
        if (!cl && !cr) break;
        if (cl && cr && a[l] != a[r]) {
            if (a[l] < a[r]) { res += 'L'; last = a[l++]; }
            else { res += 'R'; last = a[r--]; }
        } else if (cl && cr) {  // equal ends: take the longer strictly increasing run inward
            int lc = 1, i = l;
            while (i + 1 <= r && a[i + 1] > a[i]) { i++; lc++; }
            int rc = 1, j = r;
            while (j - 1 >= l && a[j - 1] > a[j]) { j--; rc++; }
            if (lc >= rc) res += string(lc, 'L'); else res += string(rc, 'R');
            break;
        } else if (cl) { res += 'L'; last = a[l++]; }
        else { res += 'R'; last = a[r--]; }
    }
    printf("%d\n%s\n", (int)res.size(), res.c_str());
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    static char buf[200005];
    while (t--) {
        int n; scanf("%d %s", &n, buf);
        vector<int> len;  // run lengths of equal characters
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && buf[j] == buf[i]) j++;
            len.push_back(j - i);
            i = j;
        }
        int m = len.size(), i = 0, j = 0;
        long long ans = 0;
        while (i < m) {
            if (j < i) j = i;
            while (j < m && len[j] < 2) j++;  // first run of length >= 2 at or after i
            if (j < m) { len[j]--; ans++; i++; }  // delete inside it; the first run goes as a prefix
            else { ans += (m - i + 1) / 2; break; }  // all runs length 1: each op removes two runs
        }
        printf("%lld\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; scanf("%d", &n);
    vector<int> a(n);
    for (auto &x : a) scanf("%d", &x);
    multiset<int> B;
    for (int i = 0; i < n; i++) { int x; scanf("%d", &x); B.insert(x); }
    for (int i = 0; i < n; i++) {
        int need = (n - a[i]) % n;            // smallest b with (a + b) % n == 0 is need
        auto it = B.lower_bound(need);        // smallest b >= need gives the smallest wrap-free sum
        if (it == B.end()) it = B.begin();    // otherwise wrap around to the smallest b
        printf("%d%c", (a[i] + *it) % n, i + 1 < n ? ' ' : '\n');
        B.erase(it);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k; scanf("%d %d", &n, &k);
    static char buf[200005];
    scanf("%s", buf);
    string a(buf), p = a.substr(0, k);
    auto build = [&](const string &pre) {
        string y(n, '0');
        for (int i = 0; i < n; i++) y[i] = pre[i % k];
        return y;
    };
    string y = build(p);
    if (y < a) {                      // increase the length-k prefix by one (it cannot be all 9s here)
        int j = k - 1;
        while (p[j] == '9') { p[j] = '0'; j--; }
        p[j]++;
        y = build(p);
    }
    printf("%d\n%s\n", n, y.c_str());
}

