int main() {
    int T; scanf("%d", &T);
    while (T--) {
        long long r, b, k; scanf("%lld %lld %lld", &r, &b, &k);
        long long g = __gcd(r, b);
        long long lo = min(r, b) / g, hi = max(r, b) / g;
        long long longestRun = (hi - 1 + lo - 1) / lo;  // ceil((hi-1)/lo): longest same-colour run
        puts(k > longestRun ? "OBEY" : "REBEL");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m; scanf("%d %d", &n, &m);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int a, b; scanf("%d %d", &a, &b);
        adj[a].push_back(b); adj[b].push_back(a);
    }
    vector<int> t(n + 1);
    for (int i = 1; i <= n; i++) scanf("%d", &t[i]);
    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 1);
    sort(ord.begin(), ord.end(), [&](int x, int y) { return t[x] < t[y]; });  // write by topic
    vector<char> done(n + 1, 0);
    for (int v : ord) {  // simulate Johnny's rule and check the mex
        vector<int> used;
        for (int u : adj[v]) if (done[u]) used.push_back(t[u]);
        sort(used.begin(), used.end());
        int mex = 1;
        for (int x : used) { if (x == mex) mex++; else if (x > mex) break; }
        if (mex != t[v]) { puts("-1"); return 0; }
        done[v] = 1;
    }
    for (int i = 0; i < n; i++) printf("%d%c", ord[i], i + 1 < n ? ' ' : '\n');
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; long long c; scanf("%d %lld", &n, &c);
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        // connect every city to city 1; add cities in increasing order of i*c - a_i
        vector<int> ord;
        for (int i = 2; i <= n; i++) ord.push_back(i);
        sort(ord.begin(), ord.end(), [&](int x, int y) {
            return (long long)x * c - a[x] < (long long)y * c - a[y];
        });
        long long S = a[1];  // total population in city 1's component
        bool ok = true;
        for (int i : ord) {
            if (S < (long long)i * c - a[i]) { ok = false; break; }  // need S + a_i >= i*c
            S += a[i];
        }
        puts(ok ? "YES" : "NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, m, q; scanf("%d %d %d", &n, &m, &q);
        vector<long long> a(n + 1), b(m + 1), PA(n + 1, 0), PB(m + 1, 0);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        for (int i = 1; i <= m; i++) scanf("%lld", &b[i]);
        sort(a.begin() + 1, a.end(), greater<long long>());
        sort(b.begin() + 1, b.end(), greater<long long>());
        for (int i = 1; i <= n; i++) PA[i] = PA[i - 1] + a[i];
        for (int i = 1; i <= m; i++) PB[i] = PB[i - 1] + b[i];
        while (q--) {
            int x, y, z; scanf("%d %d %d", &x, &y, &z);
            int L = max(0, z - y), R = min(x, z);  // k cards from Vadim, z-k from Kostya
            while (L < R) {  // the gain a[k] - b[z-k+1] is non-increasing in k
                int mid = (L + R + 1) / 2;
                if (a[mid] >= b[z - mid + 1]) L = mid; else R = mid - 1;
            }
            printf("%lld\n", PA[L] + PB[z - L]);
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, k; scanf("%d %d", &n, &k);
        vector<int> fr(k);
        for (auto &x : fr) scanf("%d", &x);
        vector<vector<int>> adj(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v; scanf("%d %d", &u, &v);
            adj[u].push_back(v); adj[v].push_back(u);
        }
        // dist[v] = earliest time any friend can stand in v
        vector<int> dist(n + 1, -1);
        queue<int> q;
        for (int x : fr) { dist[x] = 0; q.push(x); }
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int u : adj[v]) if (dist[u] < 0) { dist[u] = dist[v] + 1; q.push(u); }
        }
        // Vlad walks from room 1; he may enter v only if he gets there strictly before any friend
        vector<int> dep(n + 1, -1);
        dep[1] = 0; q.push(1);
        bool yes = false;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            if (v != 1 && adj[v].size() == 1) { yes = true; break; }
            for (int u : adj[v]) {
                if (dep[u] >= 0) continue;
                if (dep[v] + 1 < dist[u]) { dep[u] = dep[v] + 1; q.push(u); }
            }
        }
        puts(yes ? "YES" : "NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m; scanf("%d %d", &n, &m);
    int L = n;  // shortest query length
    for (int i = 0; i < m; i++) {
        int l, r; scanf("%d %d", &l, &r);
        L = min(L, r - l + 1);
    }
    // the answer cannot exceed the shortest length; the repeating pattern 0..L-1 reaches it
    printf("%d\n", L);
    for (int i = 0; i < n; i++) printf("%d%c", i % L, i + 1 < n ? ' ' : '\n');
}
